			sizes="192x192"
			href="" + assets + "/voicebook-mark-192.png"
		/>
		<link rel="apple-touch-icon" href="" + assets + "/voicebook-mark-192.png" />
		" + head + "
	</head>
	<body data-sveltekit-preload-data="hover">
		<div style="display: contents">" + body + "</div>
	</body>
</html>
",
+		error
+	},
+	version_hash: "6kzrff"
+};
